// TestSearchSpecsSingleFetchKind pins the interactive search spec (box 1.7):
// the movie search by default, the tv search when the kind param names tv —
// each under the shared request contract (language + server-scoped secret
// reference, light 250 ms pacing, GET) and each a SINGLE-FETCH plan: one
// spec, no extras, the {title} variable carrying the query.
func TestSearchSpecsSingleFetchKind(t *testing.T) {
	cases := []struct {
		name    string
		req     *metadatav1.SearchSpecsRequest
		wantURL string
	}{
		{
			name:    "movie is the default",
			req:     &metadatav1.SearchSpecsRequest{Query: "Fight Club"},
			wantURL: defaultAPIBase + "/search/movie?query={title}" + sharedParams,
		},
		{
			name:    "the kind param picks the tv search",
			req:     &metadatav1.SearchSpecsRequest{Query: "Breaking Bad", Kind: kindTV},
			wantURL: defaultAPIBase + "/search/tv?query={title}" + sharedParams,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res, err := (&sourceImpl{}).SearchSpecs(context.Background(), tc.req)
			if err != nil {
				t.Fatalf("SearchSpecs: %v", err)
			}
			if res.GetSpec() == nil {
				t.Fatal("SearchSpecs returned no spec")
			}
			spec := res.GetSpec()
			if spec.GetMethod() != "GET" {
				t.Errorf("method = %q, want GET", spec.GetMethod())
			}
			if spec.GetUrlTemplate() != tc.wantURL {
				t.Errorf("url_template = %q, want %q", spec.GetUrlTemplate(), tc.wantURL)
			}
			if spec.GetMinIntervalMs() != minIntervalMS {
				t.Errorf("min_interval_ms = %d, want %d", spec.GetMinIntervalMs(), minIntervalMS)
			}
			if v, ok := spec.GetVariables()[titleKey]; !ok || v.GetStringValue() != tc.req.GetQuery() {
				t.Errorf("variable %q = %v, want the query %q", titleKey, v, tc.req.GetQuery())
			}
			if v := spec.GetVariables()[languageVar]; v.GetStringValue() != languageRU {
				t.Errorf("variable %q = %v, want %q", languageVar, v, languageRU)
			}
			if v := spec.GetVariables()[apiKeyVar]; v.GetRedactedRef() != apiKeyRef {
				t.Errorf("variable %q = %v, want the redacted ref %q", apiKeyVar, v, apiKeyRef)
			}
			if len(spec.GetVariables()) != 3 {
				t.Errorf("variables = %d entries, want exactly {%s, %s, %s}",
					len(spec.GetVariables()), titleKey, languageVar, apiKeyVar)
			}
		})
	}
}

// TestSearchResultsCandidateMaps pins the candidate conversion (box 1.7): the
// fetched payload converts into candidates in served order — external_id the
// tmdb id, title the original-language title with russian_title carrying the
// ru-RU-served localization, year/kind/episodes/poster present only where the
// payload serves them (proto3 field presence) — while a valid empty list
// yields zero candidates and a failed fetch errors (the api maps the
// canonical upstream answer).
func TestSearchResultsCandidateMaps(t *testing.T) {
	cases := []struct {
		name    string
		req     *metadatav1.SearchResultsRequest
		want    []*metadatav1.SearchCandidate
		wantErr string
	}{
		{
			name: "served order with RU-first titles and honest presence",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true,
				Body: []byte(`{"page": 1, "results": [
					{"id": 550, "title": "Бойцовский клуб", "original_title": "Fight Club",
					 "release_date": "1999-10-15", "poster_path": "/pB8BM7pdSp6B6Ie7kZOZ.jpg"},
					{"id": 1396, "name": "Во все тяжкие", "original_name": "Breaking Bad",
					 "first_air_date": "2008-01-20", "number_of_episodes": 62}
				]}`),
			}},
			want: []*metadatav1.SearchCandidate{
				{
					ExternalId:   "550",
					Title:        "Fight Club",
					Kind:         kindMovie,
					RussianTitle: proto.String("Бойцовский клуб"),
					Year:         proto.Int32(1999),
					Poster:       proto.String(imageBase + "/pB8BM7pdSp6B6Ie7kZOZ.jpg"),
				},
				{
					ExternalId:   "1396",
					Title:        "Breaking Bad",
					Kind:         kindTV,
					RussianTitle: proto.String("Во все тяжкие"),
					Year:         proto.Int32(2008),
					Episodes:     proto.Int32(62),
				},
			},
		},
		{
			name: "fields absent upstream stay absent on the candidate",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true,
				Body:    []byte(`{"results": [{"id": 42, "title": "Минималист", "original_title": "Minimal"}]}`),
			}},
			want: []*metadatav1.SearchCandidate{
				{ExternalId: "42", Title: "Minimal", Kind: kindMovie, RussianTitle: proto.String("Минималист")},
			},
		},
		{
			name: "a valid empty list converts to zero candidates",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true, Body: []byte(`{"page": 1, "results": []}`),
			}},
			want: []*metadatav1.SearchCandidate{},
		},
		{
			name: "failed fetch is an error",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: false, Error: "upstream 503",
			}},
			wantErr: "upstream 503",
		},
		{
			name: "unparsable body is an error",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true, Body: []byte(`{"surprise": true}`),
			}},
			wantErr: "neither a search envelope nor a list",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res, err := (&sourceImpl{}).SearchResults(context.Background(), tc.req)
			if tc.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
					t.Fatalf("err = %v, want containing %q", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("SearchResults: %v", err)
			}
			got := res.GetCandidates()
			if len(got) != len(tc.want) {
				t.Fatalf("candidates = %d, want %d", len(got), len(tc.want))
			}
			for i, w := range tc.want {
				if !proto.Equal(got[i], w) {
					t.Errorf("candidate %d = %+v, want %+v", i, got[i], w)
				}
			}
		})
	}
}
